      "What is ChatSphere?": "¿Qué es ChatSphere?",
      "ChatSphere is a modern, safe alternative to traditional random chat platforms. It allows you to connect with people worldwide through text and video chat, with the added benefit of interest-based matching to find like-minded individuals for meaningful conversations.": "ChatSphere es una alternativa moderna y segura a las plataformas tradicionales de chat aleatorio. Le permite conectarse con personas de todo el mundo a través de chat de texto y video, con el beneficio adicional de coincidencias basadas en intereses para encontrar personas con ideas afines para conversaciones significativas.",
      "Why choose ChatSphere to chat with strangers?": "¿Por qué elegir ChatSphere para chatear con desconocidos?",
      "ChatSphere offers a superior chat experience with interest-based matching, active moderation, and a clean interface. Our platform prioritizes user safety and provides both text and video chat options, making it easier to connect with people who share your interests.": "ChatSphere ofrece una experiencia de chat superior con coincidencias basadas en intereses, moderación activa y una interfaz limpia. Nuestra plataforma prioriza la seguridad del usuario y ofrece opciones de chat de texto y video, lo que facilita la conexión con personas que comparten sus intereses.",
      "Who can use ChatSphere?": "¿Quién puede utilizar ChatSphere?",
      "ChatSphere is designed for adults aged 18 and above. We maintain a strict adults-only policy to ensure a safe and appropriate environment for all users. Users must comply with our community guidelines and terms of service.": "ChatSphere está diseñado para adultos mayores de 18 años. Mantenemos una estricta política solo para adultos para garantizar un entorno seguro y apropiado para todos los usuarios. Los usuarios deben cumplir con nuestras pautas comunitarias y términos de servicio.",
      "Is ChatSphere safe? Is my data secure?": "¿Es segura la Web ChatSphere? ¿Están mis datos seguros?",
      "Yes, ChatSphere prioritizes user safety and data security. We employ active moderation, especially for video chats, and implement security measures to protect user privacy. We may log chats, reports, technical identifiers, and moderation evidence as described in our Privacy Policy, and the platform includes features to report inappropriate behavior.": "Sí, ChatSphere prioriza la seguridad del usuario y de los datos. Empleamos moderación activa, especialmente para chats de video, e implementamos medidas de seguridad para proteger la privacidad del usuario. Podemos registrar chats, informes, identificadores técnicos y evidencia de moderación como se describe en nuestra Política de Privacidad, y la plataforma incluye funciones para informar comportamientos inapropiados.",
      "Are you affiliated with ChatSphere.com or Ome.tv?": "¿Está afiliado a ChatSphere.com u Ome.tv?",
      "No, ChatSphere is an independent platform and is not affiliated with ChatSphere.com or Ome.tv. We are a separate service offering our own unique features and safety measures for random chat experiences.": "No, ChatSphere es una plataforma independiente y no está afiliada a ChatSphere.com ni a Ome.tv. Somos un servicio independiente que ofrece nuestras propias características únicas y medidas de seguridad para experiencias de chat aleatorias.",
      "How do I start chatting on ChatSphere?": "¿Cómo empiezo a chatear en ChatSphere?",
      "Starting a chat is simple: just choose between text or video chat, optionally add your interests for better matching, and click the respective button to begin. You'll be connected with a random stranger who matches your preferences.": "Iniciar un chat es simple: simplemente elija entre chat de texto o video, opcionalmente agregue sus intereses para una mejor coincidencia y haga clic en el botón respectivo para comenzar. Te conectarás con un extraño al azar que coincida con tus preferencias.",
      "What features does ChatSphere offer?": "¿Qué funciones ofrece ChatSphere?",
      "ChatSphere features include text and video chat, interest-based matching, active moderation, user reporting tools, and a clean, modern interface. Our platform is designed to facilitate meaningful connections while maintaining user safety.": "Las funciones web de ChatSphere incluyen chat de texto y vídeo, coincidencias basadas en intereses, moderación activa, herramientas de informes de usuarios y una interfaz limpia y moderna. Nuestra plataforma está diseñada para facilitar conexiones significativas manteniendo la seguridad del usuario.",
      "Can I use ChatSphere without a webcam?": "¿Puedo usar ChatSphere sin una cámara web?",
      "Yes, you can use ChatSphere without a webcam. Our text chat feature allows you to connect with others using text-only communication. Video chat is completely optional and only available if you choose to use it.": "Sí, puedes utilizar ChatSphere sin una cámara web. Nuestra función de chat de texto le permite conectarse con otras personas mediante comunicación de solo texto. El video chat es completamente opcional y solo está disponible si eliges usarlo.",
      "Is there an ChatSphere app available?": "¿Existe una aplicación web de ChatSphere disponible?",
      "Currently, ChatSphere is available as a web-based platform that works perfectly on both desktop and mobile browsers. This means you can access all features without downloading any additional software.": "Actualmente, ChatSphere está disponible como una plataforma basada en web que funciona perfectamente tanto en navegadores de escritorio como móviles. Esto significa que puede acceder a todas las funciones sin descargar ningún software adicional.",
      "How is ChatSphere different from other random chat platforms?": "¿En qué se diferencia ChatSphere de otras plataformas de chat aleatorio?",
      "ChatSphere stands out with its modern interface, enhanced safety features, active moderation, and interest-based matching system. We focus on creating meaningful connections while maintaining user privacy and security.": "ChatSphere se destaca por su interfaz moderna, funciones de seguridad mejoradas, moderación activa y sistema de emparejamiento basado en intereses. Nos enfocamos en crear conexiones significativas mientras mantenemos la privacidad y seguridad del usuario.",
      "Are there any costs to use ChatSphere?": "¿Hay algún costo por usar ChatSphere?",
      "No, ChatSphere is completely free to use. All our core features, including text and video chat, are available at no cost. We maintain the service through minimal advertising and user donations.": "No, ChatSphere es de uso completamente gratuito. Todas nuestras funciones principales, incluido el chat de texto y video, están disponibles sin costo alguno. Mantenemos el servicio a través de publicidad mínima y donaciones de los usuarios.",
      "© 2026 ChatSphere.com - All rights reserved.": "© 2026 ChatSphere.com - Todos los derechos reservados.",
      "© 2026 ChatSphere": "© 2026 ChatSphere",
      "Contact us": "Contáctenos",
      "Privacy": "Privacidad",
      "Provide Feedback": "Proporcionar comentarios",
      "Send Feedback": "Enviar comentarios",
