      "What is ChatSphere?": "Qu’est-ce qu’ChatSphere?",
      "ChatSphere is a modern, safe alternative to traditional random chat platforms. It allows you to connect with people worldwide through text and video chat, with the added benefit of interest-based matching to find like-minded individuals for meaningful conversations.": "ChatSphere est une alternative moderne et sûre aux plateformes de chat aléatoire traditionnelles. Il vous permet de vous connecter avec des personnes du monde entier via le chat texte et vidéo, avec l'avantage supplémentaire d'une correspondance basée sur les intérêts pour trouver des personnes partageant les mêmes idées pour des conversations significatives.",
      "Why choose ChatSphere to chat with strangers?": "Pourquoi choisir ChatSphere pour discuter avec des inconnus?",
      "ChatSphere offers a superior chat experience with interest-based matching, active moderation, and a clean interface. Our platform prioritizes user safety and provides both text and video chat options, making it easier to connect with people who share your interests.": "ChatSphere offre une expérience de chat supérieure avec une correspondance basée sur les intérêts, une modération active et une interface claire. Notre plateforme donne la priorité à la sécurité des utilisateurs et propose des options de chat texte et vidéo, facilitant la connexion avec des personnes qui partagent vos intérêts.",
      "Who can use ChatSphere?": "Qui peut utiliser ChatSphere?",
      "ChatSphere is designed for adults aged 18 and above. We maintain a strict adults-only policy to ensure a safe and appropriate environment for all users. Users must comply with our community guidelines and terms of service.": "ChatSphere est conçu pour les adultes âgés de 18 ans et plus. Nous maintenons une politique stricte réservée aux adultes afin de garantir un environnement sûr et approprié pour tous les utilisateurs. Les utilisateurs doivent se conformer aux directives de notre communauté et à nos conditions de service.",
      "Is ChatSphere safe? Is my data secure?": "ChatSphere est-il sûr? Mes données sont-elles sécurisées?",
      "Yes, ChatSphere prioritizes user safety and data security. We employ active moderation, especially for video chats, and implement security measures to protect user privacy. We may log chats, reports, technical identifiers, and moderation evidence as described in our Privacy Policy, and the platform includes features to report inappropriate behavior.": "Oui, ChatSphere donne la priorité à la sécurité des utilisateurs et à la sécurité des données. Nous utilisons une modération active, en particulier pour les chats vidéo, et mettons en œuvre des mesures de sécurité pour protéger la confidentialité des utilisateurs. Nous pouvons enregistrer des discussions, des rapports, des identifiants techniques et des preuves de modération comme décrit dans notre Politique de confidentialité, et la plateforme comprend des fonctionnalités permettant de signaler un comportement inapproprié.",
      "Are you affiliated with ChatSphere.com or Ome.tv?": "Êtes-vous affilié à ChatSphere.com ou Ome.tv?",
      "No, ChatSphere is an independent platform and is not affiliated with ChatSphere.com or Ome.tv. We are a separate service offering our own unique features and safety measures for random chat experiences.": "Non, ChatSphere est une plateforme indépendante et n'est pas affiliée à ChatSphere.com ou Ome.tv. Nous sommes un service distinct offrant nos propres fonctionnalités et mesures de sécurité pour des expériences de chat aléatoires.",
      "How do I start chatting on ChatSphere?": "Comment puis-je commencer à discuter sur ChatSphere?",
      "Starting a chat is simple: just choose between text or video chat, optionally add your interests for better matching, and click the respective button to begin. You'll be connected with a random stranger who matches your preferences.": "Démarrer un chat est simple: choisissez simplement entre un chat texte ou vidéo, ajoutez éventuellement vos intérêts pour une meilleure correspondance, et cliquez sur le bouton correspondant pour commencer. Vous serez connecté avec un inconnu au hasard qui correspond à vos préférences.",
      "What features does ChatSphere offer?": "Quelles fonctionnalités propose ChatSphere?",
      "ChatSphere features include text and video chat, interest-based matching, active moderation, user reporting tools, and a clean, modern interface. Our platform is designed to facilitate meaningful connections while maintaining user safety.": "Les fonctionnalités Web d'ChatSphere incluent le chat texte et vidéo, la correspondance basée sur les intérêts, la modération active, les outils de reporting des utilisateurs et une interface claire et moderne. Notre plateforme est conçue pour faciliter des connexions significatives tout en préservant la sécurité des utilisateurs.",
      "Can I use ChatSphere without a webcam?": "Puis-je utiliser ChatSphere sans webcam?",
      "Yes, you can use ChatSphere without a webcam. Our text chat feature allows you to connect with others using text-only communication. Video chat is completely optional and only available if you choose to use it.": "Oui, vous pouvez utiliser ChatSphere sans webcam. Notre fonction de chat textuel vous permet de vous connecter avec d'autres personnes en utilisant uniquement une communication textuelle. Le chat vidéo est totalement facultatif et disponible uniquement si vous choisissez de l'utiliser.",
      "Is there an ChatSphere app available?": "Existe-t-il une application Web ChatSphere disponible?",
      "Currently, ChatSphere is available as a web-based platform that works perfectly on both desktop and mobile browsers. This means you can access all features without downloading any additional software.": "Actuellement, ChatSphere est disponible en tant que plate-forme Web qui fonctionne parfaitement sur les navigateurs de bureau et mobiles. Cela signifie que vous pouvez accéder à toutes les fonctionnalités sans télécharger de logiciel supplémentaire.",
      "How is ChatSphere different from other random chat platforms?": "En quoi ChatSphere est-il différent des autres plateformes de chat aléatoire?",
      "ChatSphere stands out with its modern interface, enhanced safety features, active moderation, and interest-based matching system. We focus on creating meaningful connections while maintaining user privacy and security.": "ChatSphere se distingue par son interface moderne, ses fonctionnalités de sécurité améliorées, sa modération active et son système de correspondance basé sur les intérêts. Nous nous concentrons sur la création de connexions significatives tout en préservant la confidentialité et la sécurité des utilisateurs.",
      "Are there any costs to use ChatSphere?": "Y a-t-il des frais pour utiliser ChatSphere?",
      "No, ChatSphere is completely free to use. All our core features, including text and video chat, are available at no cost. We maintain the service through minimal advertising and user donations.": "Non, l’utilisation d’ChatSphere est totalement gratuite. Toutes nos fonctionnalités principales, y compris le chat texte et vidéo, sont disponibles gratuitement. Nous maintenons le service grâce à un minimum de publicité et de dons des utilisateurs.",
      "© 2026 ChatSphere.com - All rights reserved.": "© 2026 ChatSphere.com - Tous droits réservés.",
