      "A free ChatSphere alternative for random video chat and text chat with strangers. . Interest matching, moderation, and no sign-up.": "Eine kostenlose ChatSphere-Alternative für zufälligen Video-Chat und Text-Chat mit Fremden. Nur 18+. Interessenabgleich, Moderation und keine Anmeldung.",
