      "Adults only (18+)": "Somente adultos (18+)",
      "Users must be 18 or older. We maintain a strict adults-only policy for a safer chat experience. Please follow our": "Os usuários devem ter 18 anos ou mais. Mantemos uma política rígida apenas para adultos para uma experiência de bate-papo mais segura. Por favor, siga nosso",
