      "Guides for better random chats": "Guias para melhores bate-papos aleatórios",
      "Practical tips on safety, interests, and making quick conversations feel less awkward.": "Dicas práticas sobre segurança, interesses e como fazer com que conversas rápidas pareçam menos estranhas.",
