      "Random video chat safety tips": "Dicas de segurança para chats de vídeo aleatórios",
      "What to avoid sharing, when to skip, and how reporting helps the community.": "O que evitar compartilhar, quando pular e como denunciar ajuda a comunidade.",
      "Matching": "Correspondência",
      "Use interests to match faster": "Use interesses para combinar mais rapidamente",
      "Choose focused topics so the matchmaker has a better signal.": "Escolha tópicos específicos para que o matchmaker tenha um sinal melhor.",
      "Read all posts": "Leia todas as postagens",
      "Frequently Asked Questions": "Perguntas frequentes",
      "What is ChatSphere?": "O que é ChatSphere?",
      "ChatSphere is a modern, safe alternative to traditional random chat platforms. It allows you to connect with people worldwide through text and video chat, with the added benefit of interest-based matching to find like-minded individuals for meaningful conversations.": "ChatSphere é uma alternativa moderna e segura às plataformas tradicionais de chat aleatório. Ele permite que você se conecte com pessoas de todo o mundo por meio de chat de texto e vídeo, com o benefício adicional de correspondência baseada em interesses para encontrar pessoas com ideias semelhantes para conversas significativas.",
      "Why choose ChatSphere to chat with strangers?": "Por que escolher o ChatSphere para conversar com estranhos?",
      "ChatSphere offers a superior chat experience with interest-based matching, active moderation, and a clean interface. Our platform prioritizes user safety and provides both text and video chat options, making it easier to connect with people who share your interests.": "ChatSphere oferece uma experiência de bate-papo superior com correspondência baseada em interesses, moderação ativa e uma interface limpa. Nossa plataforma prioriza a segurança do usuário e oferece opções de chat por texto e vídeo, facilitando a conexão com pessoas que compartilham seus interesses.",
      "Who can use ChatSphere?": "Quem pode usar o ChatSphere?",
      "ChatSphere is designed for adults aged 18 and above. We maintain a strict adults-only policy to ensure a safe and appropriate environment for all users. Users must comply with our community guidelines and terms of service.": "ChatSphere foi projetado para adultos com 18 anos ou mais. Mantemos uma política rigorosa apenas para adultos para garantir um ambiente seguro e apropriado para todos os usuários. Os usuários devem cumprir as diretrizes da comunidade e os termos de serviço.",
      "Is ChatSphere safe? Is my data secure?": "O ChatSphere é seguro? Meus dados estão seguros?",
      "Yes, ChatSphere prioritizes user safety and data security. We employ active moderation, especially for video chats, and implement security measures to protect user privacy. We may log chats, reports, technical identifiers, and moderation evidence as described in our Privacy Policy, and the platform includes features to report inappropriate behavior.": "Sim, o ChatSphere prioriza a segurança do usuário e a segurança dos dados. Empregamos moderação ativa, especialmente para chats de vídeo, e implementamos medidas de segurança para proteger a privacidade do usuário. Podemos registrar bate-papos, denúncias, identificadores técnicos e evidências de moderação conforme descrito em nossa Política de Privacidade, e a plataforma inclui recursos para denunciar comportamento inadequado.",
      "Are you affiliated with ChatSphere.com or Ome.tv?": "Você é afiliado ao ChatSphere.com ou Ome.tv?",
      "No, ChatSphere is an independent platform and is not affiliated with ChatSphere.com or Ome.tv. We are a separate service offering our own unique features and safety measures for random chat experiences.": "Não, ChatSphere é uma plataforma independente e não é afiliada ao ChatSphere.com ou Ome.tv. Somos um serviço separado que oferece recursos exclusivos e medidas de segurança para experiências de bate-papo aleatórias.",
      "How do I start chatting on ChatSphere?": "Como começo a conversar no ChatSphere?",
      "Starting a chat is simple: just choose between text or video chat, optionally add your interests for better matching, and click the respective button to begin. You'll be connected with a random stranger who matches your preferences.": "Iniciar um chat é simples: basta escolher entre chat de texto ou vídeo, opcionalmente adicionar seus interesses para melhor correspondência e clicar no respectivo botão para começar. Você estará conectado com um estranho aleatório que corresponda às suas preferências.",
      "What features does ChatSphere offer?": "Quais recursos o ChatSphere oferece?",
      "ChatSphere features include text and video chat, interest-based matching, active moderation, user reporting tools, and a clean, modern interface. Our platform is designed to facilitate meaningful connections while maintaining user safety.": "Os recursos do ChatSphere incluem bate-papo por texto e vídeo, correspondência com base em interesses, moderação ativa, ferramentas de relatórios de usuários e uma interface limpa e moderna. Nossa plataforma foi projetada para facilitar conexões significativas e, ao mesmo tempo, manter a segurança do usuário.",
      "Can I use ChatSphere without a webcam?": "Posso usar o ChatSphere sem webcam?",
      "Yes, you can use ChatSphere without a webcam. Our text chat feature allows you to connect with others using text-only communication. Video chat is completely optional and only available if you choose to use it.": "Sim, você pode usar o ChatSphere sem webcam. Nosso recurso de bate-papo por texto permite que você se conecte com outras pessoas usando comunicação somente por texto. O bate-papo por vídeo é totalmente opcional e só está disponível se você decidir usá-lo.",
      "Is there an ChatSphere app available?": "Existe um aplicativo da Web ChatSphere disponível?",
      "Currently, ChatSphere is available as a web-based platform that works perfectly on both desktop and mobile browsers. This means you can access all features without downloading any additional software.": "Atualmente, o ChatSphere está disponível como uma plataforma baseada na web que funciona perfeitamente em navegadores de desktop e móveis. Isso significa que você pode acessar todos os recursos sem baixar nenhum software adicional.",
      "How is ChatSphere different from other random chat platforms?": "Qual a diferença entre o ChatSphere e outras plataformas de chat aleatório?",
      "ChatSphere stands out with its modern interface, enhanced safety features, active moderation, and interest-based matching system. We focus on creating meaningful connections while maintaining user privacy and security.": "ChatSphere se destaca por sua interface moderna, recursos de segurança aprimorados, moderação ativa e sistema de correspondência baseado em interesses. Nós nos concentramos em criar conexões significativas, mantendo a privacidade e a segurança do usuário.",
      "Are there any costs to use ChatSphere?": "Há algum custo para usar o ChatSphere?",
      "No, ChatSphere is completely free to use. All our core features, including text and video chat, are available at no cost. We maintain the service through minimal advertising and user donations.": "Não, o uso do ChatSphere é totalmente gratuito. Todos os nossos principais recursos, incluindo chat de texto e vídeo, estão disponíveis gratuitamente. Mantemos o serviço por meio de publicidade mínima e doações de usuários.",
      "© 2026 ChatSphere.com - All rights reserved.": "© 2026 ChatSphere.com – Todos os direitos reservados.",
      "© 2026 ChatSphere": "© 2026 ChatSphere",
      "Contact us": "Contate-nos",
