      "ChatSphere offers a superior chat experience with interest-based matching, active moderation, and a clean interface. Our platform prioritizes user safety and provides both text and video chat options, making it easier to connect with people who share your interests.": "ChatSphere offre un'esperienza di chat superiore con corrispondenza basata sugli interessi, moderazione attiva e un'interfaccia pulita. La nostra piattaforma dà priorità alla sicurezza degli utenti e fornisce opzioni di chat sia di testo che video, semplificando la connessione con persone che condividono i tuoi interessi.",
      "Who can use ChatSphere?": "Chi può utilizzare ChatSphere?",
      "ChatSphere is designed for adults aged 18 and above. We maintain a strict adults-only policy to ensure a safe and appropriate environment for all users. Users must comply with our community guidelines and terms of service.": "ChatSphere è progettato per adulti dai 18 anni in su. Manteniamo una rigorosa politica riservata agli adulti per garantire un ambiente sicuro e appropriato per tutti gli utenti. Gli utenti devono rispettare le nostre linee guida della community e i termini di servizio.",
      "Is ChatSphere safe? Is my data secure?": "ChatSphere è sicuro? I miei dati sono al sicuro?",
