      "ChatSphere is a modern, safe alternative to traditional random chat platforms. It allows you to connect with people worldwide through text and video chat, with the added benefit of interest-based matching to find like-minded individuals for meaningful conversations.": "ChatSphere, geleneksel rastgele sohbet platformlarına modern ve güvenli bir alternatiftir. Anlamlı sohbetler için benzer düşüncelere sahip bireyleri bulmak amacıyla ilgi alanına dayalı eşleştirmenin ek avantajıyla birlikte, metin ve görüntülü sohbet yoluyla dünya çapındaki insanlarla bağlantı kurmanıza olanak tanır.",
      "Why choose ChatSphere to chat with strangers?": "Yabancılarla sohbet etmek için neden ChatSphere'i seçmelisiniz?",
      "ChatSphere offers a superior chat experience with interest-based matching, active moderation, and a clean interface. Our platform prioritizes user safety and provides both text and video chat options, making it easier to connect with people who share your interests.": "ChatSphere, ilgi alanına dayalı eşleştirme, aktif denetim ve temiz bir arayüz ile üstün bir sohbet deneyimi sunar. Platformumuz kullanıcı güvenliğini ön planda tutuyor ve hem yazılı hem de görüntülü sohbet seçenekleri sunarak ilgi alanlarınızı paylaşan kişilerle bağlantı kurmanızı kolaylaştırıyor.",
      "Who can use ChatSphere?": "ChatSphere'i kimler kullanabilir?",
      "ChatSphere is designed for adults aged 18 and above. We maintain a strict adults-only policy to ensure a safe and appropriate environment for all users. Users must comply with our community guidelines and terms of service.": "ChatSphere, 18 yaş ve üzeri yetişkinler için tasarlanmıştır. Tüm kullanıcılar için güvenli ve uygun bir ortam sağlamak amacıyla yalnızca yetişkinlere yönelik katı bir politika sürdürüyoruz. Kullanıcılar topluluk kurallarımıza ve hizmet şartlarımıza uymalıdır.",
      "Is ChatSphere safe? Is my data secure?": "ChatSphere güvenli mi? Verilerim güvende mi?",
      "Yes, ChatSphere prioritizes user safety and data security. We employ active moderation, especially for video chats, and implement security measures to protect user privacy. We may log chats, reports, technical identifiers, and moderation evidence as described in our Privacy Policy, and the platform includes features to report inappropriate behavior.": "Evet, ChatSphere kullanıcı güvenliğine ve veri güvenliğine öncelik verir. Özellikle görüntülü sohbetler için aktif denetim uyguluyoruz ve kullanıcı gizliliğini korumak için güvenlik önlemleri uyguluyoruz. Sohbetleri, raporları, teknik tanımlayıcıları ve denetleme kanıtlarını Gizlilik Politikamızda açıklandığı şekilde kaydedebiliriz ve platform, uygunsuz davranışları bildirmeye yönelik özellikler içerir.",
      "Are you affiliated with ChatSphere.com or Ome.tv?": "ChatSphere.com veya Ome.tv'ye bağlı mısınız?",
      "No, ChatSphere is an independent platform and is not affiliated with ChatSphere.com or Ome.tv. We are a separate service offering our own unique features and safety measures for random chat experiences.": "Hayır, ChatSphere bağımsız bir platformdur ve ChatSphere.com veya Ome.tv'ye bağlı değildir. Rastgele sohbet deneyimleri için kendi benzersiz özelliklerimizi ve güvenlik önlemlerimizi sunan ayrı bir hizmetiz.",
      "How do I start chatting on ChatSphere?": "ChatSphere'de sohbete nasıl başlayabilirim?",
      "Starting a chat is simple: just choose between text or video chat, optionally add your interests for better matching, and click the respective button to begin. You'll be connected with a random stranger who matches your preferences.": "Sohbet başlatmak basittir: Metin sohbeti veya görüntülü sohbet arasında seçim yapın, isteğe bağlı olarak daha iyi eşleşme için ilgi alanlarınızı ekleyin ve başlamak için ilgili düğmeye tıklayın. Tercihlerinize uyan rastgele bir yabancıyla bağlantı kuracaksınız.",
      "What features does ChatSphere offer?": "ChatSphere hangi özellikleri sunuyor?",
      "ChatSphere features include text and video chat, interest-based matching, active moderation, user reporting tools, and a clean, modern interface. Our platform is designed to facilitate meaningful connections while maintaining user safety.": "ChatSphere özellikleri arasında metin ve görüntülü sohbet, ilgi alanına dayalı eşleştirme, aktif denetim, kullanıcı raporlama araçları ve temiz, modern bir arayüz bulunur. Platformumuz, kullanıcı güvenliğini korurken anlamlı bağlantıları kolaylaştırmak için tasarlanmıştır.",
      "Can I use ChatSphere without a webcam?": "ChatSphere'i web kamerası olmadan kullanabilir miyim?",
      "Yes, you can use ChatSphere without a webcam. Our text chat feature allows you to connect with others using text-only communication. Video chat is completely optional and only available if you choose to use it.": "Evet, ChatSphere'i web kamerası olmadan kullanabilirsiniz. Metin sohbeti özelliğimiz, yalnızca metin iletişimi kullanarak başkalarıyla bağlantı kurmanıza olanak tanır. Görüntülü sohbet tamamen isteğe bağlıdır ve yalnızca kullanmayı seçerseniz kullanılabilir.",
      "Is there an ChatSphere app available?": "ChatSphere uygulaması mevcut mu?",
      "Currently, ChatSphere is available as a web-based platform that works perfectly on both desktop and mobile browsers. This means you can access all features without downloading any additional software.": "Şu anda ChatSphere, hem masaüstü hem de mobil tarayıcılarda mükemmel şekilde çalışan web tabanlı bir platform olarak mevcuttur. Bu, herhangi bir ek yazılım indirmeden tüm özelliklere erişebileceğiniz anlamına gelir.",
      "How is ChatSphere different from other random chat platforms?": "ChatSphere'in diğer rastgele sohbet platformlarından farkı nedir?",
      "ChatSphere stands out with its modern interface, enhanced safety features, active moderation, and interest-based matching system. We focus on creating meaningful connections while maintaining user privacy and security.": "ChatSphere, modern arayüzü, gelişmiş güvenlik özellikleri, aktif moderasyonu ve ilgi alanına dayalı eşleştirme sistemiyle öne çıkıyor. Kullanıcı gizliliğini ve güvenliğini korurken anlamlı bağlantılar oluşturmaya odaklanıyoruz.",
      "Are there any costs to use ChatSphere?": "ChatSphere'i kullanmanın herhangi bir maliyeti var mı?",
      "No, ChatSphere is completely free to use. All our core features, including text and video chat, are available at no cost. We maintain the service through minimal advertising and user donations.": "Hayır, ChatSphere'in kullanımı tamamen ücretsizdir. Metin ve görüntülü sohbet de dahil olmak üzere tüm temel özelliklerimiz ücretsiz olarak mevcuttur. Hizmeti minimum düzeyde reklam ve kullanıcı bağışlarıyla sürdürüyoruz.",
      "© 2026 ChatSphere.com - All rights reserved.": "© 2026 ChatSphere.com - Tüm hakları saklıdır.",
      "© 2026 ChatSphere": "© 2026 ChatSphere",
