      "What is ChatSphere?": "ما هو موقع ChatSphere؟",
      "ChatSphere is a modern, safe alternative to traditional random chat platforms. It allows you to connect with people worldwide through text and video chat, with the added benefit of interest-based matching to find like-minded individuals for meaningful conversations.": "يعد ChatSphere بديلاً حديثًا وآمنًا لمنصات الدردشة العشوائية التقليدية. فهو يسمح لك بالتواصل مع الأشخاص في جميع أنحاء العالم من خلال الدردشة النصية والمرئية، مع ميزة إضافية تتمثل في المطابقة القائمة على الاهتمامات للعثور على أفراد متشابهين في التفكير لإجراء محادثات هادفة.",
      "Why choose ChatSphere to chat with strangers?": "لماذا تختار ChatSphere للدردشة مع الغرباء؟",
      "ChatSphere offers a superior chat experience with interest-based matching, active moderation, and a clean interface. Our platform prioritizes user safety and provides both text and video chat options, making it easier to connect with people who share your interests.": "يقدم ChatSphere تجربة دردشة متميزة مع المطابقة القائمة على الاهتمامات والإشراف النشط والواجهة النظيفة. تعطي منصتنا الأولوية لسلامة المستخدم وتوفر خيارات الدردشة النصية والمرئية، مما يسهل التواصل مع الأشخاص الذين يشاركونك اهتماماتك.",
      "Who can use ChatSphere?": "من يمكنه استخدام ChatSphere؟",
      "ChatSphere is designed for adults aged 18 and above. We maintain a strict adults-only policy to ensure a safe and appropriate environment for all users. Users must comply with our community guidelines and terms of service.": "تم تصميم ChatSphere للبالغين من عمر 18 عامًا فما فوق. نحن نحافظ على سياسة صارمة للبالغين فقط لضمان بيئة آمنة ومناسبة لجميع المستخدمين. يجب على المستخدمين الالتزام بإرشادات مجتمعنا وشروط الخدمة.",
      "Is ChatSphere safe? Is my data secure?": "هل موقع ChatSphere آمن؟ هل بياناتي آمنة؟",
      "Yes, ChatSphere prioritizes user safety and data security. We employ active moderation, especially for video chats, and implement security measures to protect user privacy. We may log chats, reports, technical identifiers, and moderation evidence as described in our Privacy Policy, and the platform includes features to report inappropriate behavior.": "نعم، يعطي موقع ChatSphere الأولوية لسلامة المستخدم وأمن البيانات. نحن نستخدم الإشراف النشط، خاصة في محادثات الفيديو، وننفذ إجراءات أمنية لحماية خصوصية المستخدم. يجوز لنا تسجيل الدردشات والتقارير والمعرفات الفنية وأدلة الإشراف كما هو موضح في سياسة الخصوصية الخاصة بنا، وتتضمن المنصة ميزات للإبلاغ عن السلوك غير اللائق.",
      "Are you affiliated with ChatSphere.com or Ome.tv?": "هل أنت تابع لـ ChatSphere.com أو Ome.tv؟",
      "No, ChatSphere is an independent platform and is not affiliated with ChatSphere.com or Ome.tv. We are a separate service offering our own unique features and safety measures for random chat experiences.": "لا، ChatSphere عبارة عن منصة مستقلة وليست تابعة لـ ChatSphere.com أو Ome.tv. نحن خدمة منفصلة تقدم ميزاتنا الفريدة وإجراءات السلامة لتجارب الدردشة العشوائية.",
      "How do I start chatting on ChatSphere?": "كيف أبدأ الدردشة على ChatSphere؟",
      "Starting a chat is simple: just choose between text or video chat, optionally add your interests for better matching, and click the respective button to begin. You'll be connected with a random stranger who matches your preferences.": "يعد بدء الدردشة أمرًا بسيطًا: ما عليك سوى الاختيار بين الدردشة النصية أو الدردشة المرئية، وإضافة اهتماماتك بشكل اختياري للحصول على مطابقة أفضل، وانقر فوق الزر المناسب للبدء. سيتم ربطك بشخص غريب عشوائيًا يتوافق مع تفضيلاتك.",
      "What features does ChatSphere offer?": "ما هي الميزات التي يقدمها ChatSphere؟",
      "ChatSphere features include text and video chat, interest-based matching, active moderation, user reporting tools, and a clean, modern interface. Our platform is designed to facilitate meaningful connections while maintaining user safety.": "تتضمن ميزات ChatSphere الدردشة النصية والمرئية، والمطابقة القائمة على الاهتمامات، والإشراف النشط، وأدوات إعداد تقارير المستخدم، وواجهة نظيفة وحديثة. تم تصميم منصتنا لتسهيل الاتصالات الهادفة مع الحفاظ على سلامة المستخدم.",
      "Can I use ChatSphere without a webcam?": "هل يمكنني استخدام ChatSphere بدون كاميرا ويب؟",
      "Yes, you can use ChatSphere without a webcam. Our text chat feature allows you to connect with others using text-only communication. Video chat is completely optional and only available if you choose to use it.": "نعم، يمكنك استخدام ChatSphere بدون كاميرا ويب. تتيح لك ميزة الدردشة النصية لدينا التواصل مع الآخرين باستخدام الاتصال النصي فقط. تعد الدردشة المرئية اختيارية تمامًا ولا تتوفر إلا إذا اخترت استخدامها.",
      "Is there an ChatSphere app available?": "هل يتوفر تطبيق ChatSphere؟",
      "Currently, ChatSphere is available as a web-based platform that works perfectly on both desktop and mobile browsers. This means you can access all features without downloading any additional software.": "حاليًا، يتوفر ChatSphere كمنصة على الويب تعمل بشكل مثالي على متصفحات سطح المكتب والجوال. وهذا يعني أنه يمكنك الوصول إلى جميع الميزات دون تنزيل أي برامج إضافية.",
      "How is ChatSphere different from other random chat platforms?": "كيف يختلف ChatSphere عن منصات الدردشة العشوائية الأخرى؟",
      "ChatSphere stands out with its modern interface, enhanced safety features, active moderation, and interest-based matching system. We focus on creating meaningful connections while maintaining user privacy and security.": "تتميز ChatSphere بواجهتها الحديثة وميزات الأمان المحسنة والإشراف النشط ونظام المطابقة القائم على الاهتمامات. نحن نركز على إنشاء اتصالات مفيدة مع الحفاظ على خصوصية المستخدم وأمانه.",
      "Are there any costs to use ChatSphere?": "هل هناك أي تكاليف لاستخدام ChatSphere؟",
      "No, ChatSphere is completely free to use. All our core features, including text and video chat, are available at no cost. We maintain the service through minimal advertising and user donations.": "لا، ChatSphere مجاني تمامًا للاستخدام. جميع ميزاتنا الأساسية، بما في ذلك الدردشة النصية والمرئية، متاحة مجانًا. نحن نحافظ على الخدمة من خلال الحد الأدنى من الإعلانات وتبرعات المستخدمين.",
