      "Read all posts": "모든 게시물 읽기",
      "Frequently Asked Questions": "자주 묻는 질문",
      "What is ChatSphere?": "ChatSphere 웹이란 무엇입니까?",
      "ChatSphere is a modern, safe alternative to traditional random chat platforms. It allows you to connect with people worldwide through text and video chat, with the added benefit of interest-based matching to find like-minded individuals for meaningful conversations.": "ChatSphere은 기존 무작위 채팅 플랫폼에 대한 현대적이고 안전한 대안입니다. 문자 및 영상 채팅을 통해 전 세계 사람들과 연결할 수 있으며, 관심 기반 매칭의 추가 혜택을 통해 의미 있는 대화를 위해 같은 생각을 가진 사람들을 찾을 수 있습니다.",
      "Why choose ChatSphere to chat with strangers?": "낯선 사람과 채팅하기 위해 ChatSphere 웹을 선택하는 이유는 무엇입니까?",
      "ChatSphere offers a superior chat experience with interest-based matching, active moderation, and a clean interface. Our platform prioritizes user safety and provides both text and video chat options, making it easier to connect with people who share your interests.": "ChatSphere은 관심 기반 매칭, 적극적인 중재 및 깔끔한 인터페이스를 통해 우수한 채팅 경험을 제공합니다. 우리 플랫폼은 사용자 안전을 최우선으로 생각하며 문자 및 영상 채팅 옵션을 모두 제공하므로 관심사를 공유하는 사람들과 더 쉽게 연결할 수 있습니다.",
      "Who can use ChatSphere?": "누가 ChatSphere 웹을 사용할 수 있나요?",
      "ChatSphere is designed for adults aged 18 and above. We maintain a strict adults-only policy to ensure a safe and appropriate environment for all users. Users must comply with our community guidelines and terms of service.": "ChatSphere은 18세 이상의 성인을 위해 설계되었습니다. 우리는 모든 사용자에게 안전하고 적절한 환경을 보장하기 위해 엄격한 성인 전용 정책을 유지합니다. 사용자는 커뮤니티 지침과 서비스 약관을 준수해야 합니다.",
      "Is ChatSphere safe? Is my data secure?": "ChatSphere 웹은 안전합니까? 내 데이터는 안전합니까?",
      "Yes, ChatSphere prioritizes user safety and data security. We employ active moderation, especially for video chats, and implement security measures to protect user privacy. We may log chats, reports, technical identifiers, and moderation evidence as described in our Privacy Policy, and the platform includes features to report inappropriate behavior.": "예, ChatSphere은 사용자 안전과 데이터 보안을 최우선으로 생각합니다. 우리는 특히 화상 채팅에 대해 적극적인 중재를 채택하고 사용자 개인 정보를 보호하기 위한 보안 조치를 구현합니다. 당사는 개인정보 보호정책에 설명된 대로 채팅, 보고서, 기술 식별자 및 조정 증거를 기록할 수 있으며 플랫폼에는 부적절한 행동을 신고하는 기능이 포함되어 있습니다.",
      "Are you affiliated with ChatSphere.com or Ome.tv?": "ChatSphere.com 또는 Ome.tv와 제휴하고 계십니까?",
      "No, ChatSphere is an independent platform and is not affiliated with ChatSphere.com or Ome.tv. We are a separate service offering our own unique features and safety measures for random chat experiences.": "아니요, ChatSphere은 독립적인 플랫폼이며 ChatSphere.com 또는 Ome.tv와 제휴하지 않습니다. 우리는 랜덤 채팅 경험을 위한 고유한 기능과 안전 조치를 제공하는 별도의 서비스입니다.",
      "How do I start chatting on ChatSphere?": "ChatSphere 웹에서 채팅을 시작하려면 어떻게 해야 하나요?",
      "Starting a chat is simple: just choose between text or video chat, optionally add your interests for better matching, and click the respective button to begin. You'll be connected with a random stranger who matches your preferences.": "채팅을 시작하는 방법은 간단합니다. 문자 또는 영상 채팅 중 하나를 선택하고 선택적으로 더 나은 매칭을 위해 관심사를 추가한 후 해당 버튼을 클릭하면 시작됩니다. 당신은 당신의 취향에 맞는 무작위 낯선 사람과 연결될 것입니다.",
      "What features does ChatSphere offer?": "ChatSphere은 어떤 기능을 제공합니까?",
      "ChatSphere features include text and video chat, interest-based matching, active moderation, user reporting tools, and a clean, modern interface. Our platform is designed to facilitate meaningful connections while maintaining user safety.": "ChatSphere 웹 기능에는 문자 및 영상 채팅, 관심 기반 매칭, 활성 조정, 사용자 보고 도구 및 깔끔하고 현대적인 인터페이스가 포함됩니다. 우리 플랫폼은 사용자 안전을 유지하면서 의미 있는 연결을 촉진하도록 설계되었습니다.",
      "Can I use ChatSphere without a webcam?": "웹캠 없이 ChatSphere 웹을 사용할 수 있나요?",
      "Yes, you can use ChatSphere without a webcam. Our text chat feature allows you to connect with others using text-only communication. Video chat is completely optional and only available if you choose to use it.": "예, 웹캠 없이도 ChatSphere 웹을 사용할 수 있습니다. 당사의 문자 채팅 기능을 사용하면 문자 전용 통신을 통해 다른 사람과 연결할 수 있습니다. 영상 채팅은 전적으로 선택 사항이며 사용을 선택한 경우에만 사용할 수 있습니다.",
      "Is there an ChatSphere app available?": "ChatSphere 웹 앱을 사용할 수 있나요?",
      "Currently, ChatSphere is available as a web-based platform that works perfectly on both desktop and mobile browsers. This means you can access all features without downloading any additional software.": "현재 ChatSphere은 데스크톱과 모바일 브라우저 모두에서 완벽하게 작동하는 웹 기반 플랫폼으로 제공됩니다. 이는 추가 소프트웨어를 다운로드하지 않고도 모든 기능에 액세스할 수 있음을 의미합니다.",
      "How is ChatSphere different from other random chat platforms?": "ChatSphere은 다른 무작위 채팅 플랫폼과 어떻게 다른가요?",
      "ChatSphere stands out with its modern interface, enhanced safety features, active moderation, and interest-based matching system. We focus on creating meaningful connections while maintaining user privacy and security.": "ChatSphere은 현대적인 인터페이스, 향상된 안전 기능, 활성 조정 및 관심 기반 매칭 시스템으로 돋보입니다. 우리는 사용자 개인 정보 보호와 보안을 유지하면서 의미 있는 연결을 만드는 데 중점을 둡니다.",
      "Are there any costs to use ChatSphere?": "ChatSphere을 사용하는 데 비용이 드나요?",
      "No, ChatSphere is completely free to use. All our core features, including text and video chat, are available at no cost. We maintain the service through minimal advertising and user donations.": "아니요, ChatSphere은 완전히 무료로 사용할 수 있습니다. 문자 및 영상 채팅을 포함한 모든 핵심 기능을 무료로 사용할 수 있습니다. 최소한의 광고와 사용자 기부를 통해 서비스를 유지합니다.",
      "© 2026 ChatSphere.com - All rights reserved.": "© 2026 ChatSphere.com - 판권 소유.",
      "© 2026 ChatSphere": "© 2026 오메글웹",
