  addVideoCoverage("Automatically search for a new stranger when a chat ends.", ["Busca automáticamente a otra persona cuando termina un chat.", "Recherchez automatiquement une nouvelle personne à la fin d'un chat.", "Suche nach Chatende automatisch nach einer neuen Person.", "Procure automaticamente outra pessoa quando uma conversa terminar.", "Cerca automaticamente un'altra persona quando termina una chat.", "Zoek automatisch een nieuwe persoon wanneer een chat eindigt.", "Sohbet bittiğinde otomatik olarak yeni birini ara.", "Cari orang baru secara otomatis saat chat berakhir.", "चैट समाप्त होने पर अपने आप किसी नए व्यक्ति को खोजें।", "ابحث تلقائيا عن شخص جديد عند انتهاء الدردشة.", "チャット終了時に自動で次の相手を探します。", "채팅이 끝나면 자동으로 새 상대를 찾습니다.", "聊天结束时自动寻找新的聊天对象。", "Автоматически ищите нового собеседника после завершения чата."]);
