  addVideoCoverage("Cancel Premium subscription? Premium stays active until the end of your current paid period, and you will not be charged again for this subscription.", ["¿Cancelar la suscripción Premium? Premium seguirá activo hasta el final del período pagado actual y no se te volverá a cobrar por esta suscripción.", "Annuler l'abonnement Premium ? Premium restera actif jusqu'à la fin de la période payée et cet abonnement ne sera plus facturé.", "Premium-Abo kündigen? Premium bleibt bis zum Ende des aktuellen bezahlten Zeitraums aktiv und wird danach nicht erneut berechnet.", "Cancelar a assinatura Premium? O Premium continuará ativo até o fim do período pago atual e esta assinatura não será cobrada novamente.", "Annullare l'abbonamento Premium? Premium resterà attivo fino alla fine del periodo pagato e non verrà addebitato di nuovo.", "Premium-abonnement opzeggen? Premium blijft actief tot het einde van de huidige betaalde periode en wordt daarna niet opnieuw in rekening gebracht.", "Premium aboneliği iptal edilsin mi? Premium mevcut ücretli dönemin sonuna kadar etkin kalır ve tekrar ücret alınmaz.", "Batalkan langganan Premium? Premium tetap aktif sampai akhir periode berbayar saat ini dan tidak akan ditagih lagi.", "Premium सदस्यता रद्द करें? Premium मौजूदा भुगतान अवधि के अंत तक सक्रिय रहेगा और दोबारा शुल्क नहीं लिया जाएगा।", "إلغاء اشتراك Premium؟ سيظل Premium فعالا حتى نهاية الفترة المدفوعة الحالية ولن يتم تحصيل رسوم مرة أخرى.", "Premiumを解約しますか？現在の支払い期間が終了するまで利用でき、その後は請求されません。", "Premium 구독을 취소할까요? 현재 결제 기간이 끝날 때까지 유지되며 다시 청구되지 않습니다.", "取消 Premium 订阅？Premium 将持续到当前付费周期结束，之后不会再次收费。", "Отменить подписку Premium? Premium останется активным до конца текущего оплаченного периода, повторных списаний не будет."]);
  addVideoCoverage("Canceling subscription...", ["Cancelando suscripción...", "Annulation de l'abonnement...", "Abo wird gekündigt...", "Cancelando assinatura...", "Annullamento abbonamento...", "Abonnement opzeggen...", "Abonelik iptal ediliyor...", "Membatalkan langganan...", "सदस्यता रद्द की जा रही है...", "جار إلغاء الاشتراك...", "解約しています...", "구독을 취소하는 중...", "正在取消订阅...", "Отмена подписки..."]);
  addVideoCoverage("Cancellation was not made. Premium is still active and can be canceled anytime.", ["No se realizó la cancelación. Premium sigue activo y puede cancelarse cuando quieras.", "L'annulation n'a pas été effectuée. Premium reste actif et peut être annulé à tout moment.", "Die Kündigung wurde nicht durchgeführt. Premium bleibt aktiv und kann jederzeit gekündigt werden.", "O cancelamento não foi realizado. O Premium continua ativo e pode ser cancelado quando quiser.", "L'annullamento non è stato effettuato. Premium è ancora attivo e può essere annullato in qualsiasi momento.", "De opzegging is niet uitgevoerd. Premium blijft actief en kan altijd worden opgezegd.", "İptal işlemi yapılmadı. Premium hala etkin ve istenildiği zaman iptal edilebilir.", "Pembatalan tidak dilakukan. Premium masih aktif dan dapat dibatalkan kapan saja.", "रद्दीकरण नहीं हुआ। Premium अभी सक्रिय है और कभी भी रद्द किया जा सकता है।", "لم يتم الإلغاء. لا يزال Premium فعالا ويمكن إلغاؤه في أي وقت.", "解約されませんでした。Premiumは有効なままで、いつでも解約できます。", "취소되지 않았습니다. Premium은 계속 활성 상태이며 언제든 취소할 수 있습니다.", "未执行取消。Premium 仍然有效，可随时取消。", "Отмена не выполнена. Premium остается активным, его можно отменить в любое время."]);
