  addVideoCoverage("Use Esc, a function key, or a Ctrl/Alt/⌘ combo. Plain letters and numbers can't be used — the chat box captures them while you're connected.", ["Usa Esc, una tecla de función o una combinación Ctrl/Alt/⌘. No se permiten letras o números solos porque el chat los captura mientras estás conectado.", "Utilisez Échap, une touche de fonction ou Ctrl/Alt/⌘. Les lettres et chiffres seuls sont réservés au chat pendant la connexion.", "Verwende Esc, eine Funktionstaste oder Ctrl/Alt/⌘. Einzelne Buchstaben und Zahlen sind im verbundenen Chat reserviert.", "Use Esc, uma tecla de função ou Ctrl/Alt/⌘. Letras e números sozinhos ficam reservados para o chat enquanto você está conectado.", "Usa Esc, un tasto funzione o Ctrl/Alt/⌘. Lettere e numeri singoli sono riservati alla chat durante la connessione.", "Gebruik Esc, een functietoets of Ctrl/Alt/⌘. Losse letters en cijfers zijn tijdens een verbinding voor de chat gereserveerd.", "Esc, bir işlev tuşu veya Ctrl/Alt/⌘ kullan. Bağlıyken tek harf ve sayılar sohbet kutusuna ayrılır.", "Gunakan Esc, tombol fungsi, atau kombinasi Ctrl/Alt/⌘. Huruf dan angka tunggal dipakai kotak chat saat terhubung.", "Esc, फ़ंक्शन कुंजी या Ctrl/Alt/⌘ संयोजन इस्तेमाल करें। कनेक्ट होने पर अकेले अक्षर और अंक चैट बॉक्स के लिए आरक्षित हैं।", "استخدم Esc أو مفتاح وظائف أو Ctrl/Alt/⌘. الأحرف والأرقام المفردة مخصصة للدردشة أثناء الاتصال.", "Esc、ファンクションキー、またはCtrl/Alt/⌘の組み合わせを使用してください。接続中は単独の文字や数字をチャット欄で使用します。", "Esc, 기능 키 또는 Ctrl/Alt/⌘ 조합을 사용하세요. 연결 중에는 단일 문자와 숫자가 채팅 입력에 사용됩니다.", "请使用 Esc、功能键或 Ctrl/Alt/⌘ 组合。连接时，单独的字母和数字会用于聊天输入框。", "Используйте Esc, функциональную клавишу или сочетание Ctrl/Alt/⌘. Одиночные буквы и цифры во время подключения вводятся в чат."]);
