  addVideoCoverage("Allow camera and microphone access in your browser, then tap Allow Camera.", ["Permite el acceso a cámara y micrófono en tu navegador y toca Permitir cámara.", "Autorisez la caméra et le microphone dans votre navigateur, puis touchez Autoriser la caméra.", "Erlaube Kamera und Mikrofon im Browser und tippe dann auf Kamera erlauben.", "Permita câmera e microfone no navegador e toque em Permitir câmera.", "Consenti fotocamera e microfono nel browser, poi tocca Consenti fotocamera.", "Sta camera en microfoon toe in je browser en tik daarna op Camera toestaan.", "Tarayıcıda kamera ve mikrofona izin ver, ardından Kameraya izin ver'e dokun.", "Izinkan kamera dan mikrofon di browser, lalu ketuk Izinkan kamera.", "ब्राउज़र में कैमरा और माइक्रोफ़ोन की अनुमति दें, फिर कैमरे की अनुमति दें पर टैप करें।", "اسمح للكاميرا والميكروفون في المتصفح، ثم اضغط السماح بالكاميرا.", "ブラウザでカメラとマイクを許可し、「カメラを許可」をタップしてください。", "브라우저에서 카메라와 마이크를 허용한 후 카메라 허용을 누르세요.", "请在浏览器中允许摄像头和麦克风，然后点按允许摄像头。", "Разрешите камеру и микрофон в браузере, затем нажмите «Разрешить камеру»."]);
  addVideoCoverage("Camera and microphone are required. Connect both devices, then tap Allow Camera.", ["Se requieren cámara y micrófono. Conecta ambos dispositivos y toca Permitir cámara.", "La caméra et le microphone sont requis. Connectez-les, puis touchez Autoriser la caméra.", "Kamera und Mikrofon sind erforderlich. Verbinde beide Geräte und tippe auf Kamera erlauben.", "Câmera e microfone são obrigatórios. Conecte os dois e toque em Permitir câmera.", "Fotocamera e microfono sono obbligatori. Collegali e tocca Consenti fotocamera.", "Camera en microfoon zijn vereist. Sluit beide aan en tik op Camera toestaan.", "Kamera ve mikrofon gerekli. İkisini de bağla ve Kameraya izin ver'e dokun.", "Kamera dan mikrofon diperlukan. Hubungkan keduanya lalu ketuk Izinkan kamera.", "कैमरा और माइक्रोफ़ोन आवश्यक हैं। दोनों कनेक्ट करें, फिर कैमरे की अनुमति दें पर टैप करें।", "الكاميرا والميكروفون مطلوبان. وصلهما ثم اضغط السماح بالكاميرا.", "カメラとマイクが必要です。両方を接続して「カメラを許可」をタップしてください。", "카메라와 마이크가 필요합니다. 둘 다 연결한 후 카메라 허용을 누르세요.", "需要摄像头和麦克风。请连接两者，然后点按允许摄像头。", "Требуются камера и микрофон. Подключите оба устройства и нажмите «Разрешить камеру»."]);
  addVideoCoverage("Camera or microphone is already in use. Close other apps, then tap Allow Camera.", ["La cámara o el micrófono ya están en uso. Cierra otras aplicaciones y toca Permitir cámara.", "La caméra ou le microphone est déjà utilisé. Fermez les autres applications, puis touchez Autoriser la caméra.", "Kamera oder Mikrofon wird bereits verwendet. Schließe andere Apps und tippe auf Kamera erlauben.", "A câmera ou o microfone já está em uso. Feche outros apps e toque em Permitir câmera.", "La fotocamera o il microfono è già in uso. Chiudi le altre app e tocca Consenti fotocamera.", "Camera of microfoon is al in gebruik. Sluit andere apps en tik op Camera toestaan.", "Kamera veya mikrofon kullanımda. Diğer uygulamaları kapat ve Kameraya izin ver'e dokun.", "Kamera atau mikrofon sedang digunakan. Tutup aplikasi lain lalu ketuk Izinkan kamera.", "कैमरा या माइक्रोफ़ोन पहले से इस्तेमाल हो रहा है। दूसरे ऐप बंद करें, फिर कैमरे की अनुमति दें पर टैप करें।", "الكاميرا أو الميكروفون قيد الاستخدام. أغلق التطبيقات الأخرى ثم اضغط السماح بالكاميرا.", "カメラまたはマイクが使用中です。他のアプリを閉じて「カメラを許可」をタップしてください。", "카메라 또는 마이크가 사용 중입니다. 다른 앱을 닫고 카메라 허용을 누르세요.", "摄像头或麦克风正在使用中。请关闭其他应用，然后点按允许摄像头。", "Камера или микрофон уже используется. Закройте другие приложения и нажмите «Разрешить камеру»."]);
  addVideoCoverage("Camera and microphone are not available in this browser.", ["La cámara y el micrófono no están disponibles en este navegador.", "La caméra et le microphone ne sont pas disponibles dans ce navigateur.", "Kamera und Mikrofon sind in diesem Browser nicht verfügbar.", "Câmera e microfone não estão disponíveis neste navegador.", "Fotocamera e microfono non sono disponibili in questo browser.", "Camera en microfoon zijn niet beschikbaar in deze browser.", "Bu tarayıcıda kamera ve mikrofon kullanılamıyor.", "Kamera dan mikrofon tidak tersedia di browser ini.", "इस ब्राउज़र में कैमरा और माइक्रोफ़ोन उपलब्ध नहीं हैं।", "الكاميرا والميكروفون غير متاحين في هذا المتصفح.", "このブラウザではカメラとマイクを利用できません。", "이 브라우저에서는 카메라와 마이크를 사용할 수 없습니다.", "此浏览器无法使用摄像头和麦克风。", "Камера и микрофон недоступны в этом браузере."]);
