  addVideoCoverage("Your subscription cancellation is confirmed. Premium stays active until the end of the current paid period. You will not be charged again for this subscription.", ["La cancelación está confirmada. Premium seguirá activo hasta el final del período pagado actual. No se te volverá a cobrar por esta suscripción.", "L'annulation est confirmée. Premium reste actif jusqu'à la fin de la période payée. Cet abonnement ne sera plus facturé.", "Die Kündigung ist bestätigt. Premium bleibt bis zum Ende des aktuellen bezahlten Zeitraums aktiv. Es erfolgt keine weitere Abbuchung.", "O cancelamento está confirmado. O Premium continua ativo até o fim do período pago atual. Esta assinatura não será cobrada novamente.", "L'annullamento è confermato. Premium resta attivo fino alla fine del periodo pagato. Non verrà addebitato di nuovo.", "De opzegging is bevestigd. Premium blijft actief tot het einde van de huidige betaalde periode. Er wordt niet opnieuw afgeschreven.", "İptal onaylandı. Premium mevcut ücretli dönemin sonuna kadar etkin kalır. Tekrar ücret alınmaz.", "Pembatalan dikonfirmasi. Premium tetap aktif sampai akhir periode berbayar saat ini. Tidak akan ditagih lagi.", "रद्दीकरण की पुष्टि हुई। Premium मौजूदा भुगतान अवधि के अंत तक सक्रिय रहेगा। दोबारा शुल्क नहीं लिया जाएगा।", "تم تأكيد الإلغاء. سيظل Premium فعالا حتى نهاية الفترة المدفوعة الحالية. لن يتم تحصيل رسوم مرة أخرى.", "解約を確認しました。現在の支払い期間が終了するまでPremiumを利用でき、その後は請求されません。", "취소가 확인되었습니다. 현재 결제 기간이 끝날 때까지 Premium이 유지되며 다시 청구되지 않습니다.", "已确认取消。Premium 将持续到当前付费周期结束，之后不会再次收费。", "Отмена подтверждена. Premium останется активным до конца текущего оплаченного периода. Повторных списаний не будет."]);
  addVideoCoverage("Your subscription cancellation is confirmed. Premium stays active until {date}. You will not be charged again for this subscription.", ["La cancelación está confirmada. Premium seguirá activo hasta {date}. No se te volverá a cobrar por esta suscripción.", "L'annulation est confirmée. Premium reste actif jusqu'au {date}. Cet abonnement ne sera plus facturé.", "Die Kündigung ist bestätigt. Premium bleibt bis {date} aktiv. Es erfolgt keine weitere Abbuchung.", "O cancelamento está confirmado. O Premium continua ativo até {date}. Esta assinatura não será cobrada novamente.", "L'annullamento è confermato. Premium resta attivo fino al {date}. Non verrà addebitato di nuovo.", "De opzegging is bevestigd. Premium blijft actief tot {date}. Er wordt niet opnieuw afgeschreven.", "İptal onaylandı. Premium {date} tarihine kadar etkin kalır. Tekrar ücret alınmaz.", "Pembatalan dikonfirmasi. Premium tetap aktif sampai {date}. Tidak akan ditagih lagi.", "रद्दीकरण की पुष्टि हुई। Premium {date} तक सक्रिय रहेगा। दोबारा शुल्क नहीं लिया जाएगा।", "تم تأكيد الإلغاء. سيظل Premium فعالا حتى {date}. لن يتم تحصيل رسوم مرة أخرى.", "解約を確認しました。Premiumは{date}まで有効で、その後は請求されません。", "취소가 확인되었습니다. Premium은 {date}까지 유지되며 다시 청구되지 않습니다.", "已确认取消。Premium 将持续到 {date}，之后不会再次收费。", "Отмена подтверждена. Premium останется активным до {date}. Повторных списаний не будет."]);
